        balance -= amount;
        return true;
    }

    int getBalance() const {
        return balance;
    }
};

int main() {
    int start, added, taken;
    cin >> start >> added >> taken;
    BankAccount account(start);
    account.deposit(added);
    cout << account.getBalance() << endl;
    if (account.withdraw(taken)) {
        cout << account.getBalance() << endl;
    } else {
        cout << "insufficient funds" << endl;
    }
    return 0;
}

