#include <iostream>

class Counter
{
public:
    Counter(int start) : value(start) {}
    void add(int amount) { value += amount; }
    int get() const { return value; }

private:
    int value;
};

void report(Counter* counter)
{
    std::cout << counter->get() << std::endl;
}

int main()
{
    int start, step;
    std::cin >> start >> step;
    Counter* counter = new Counter(start);
    counter->add(step);
    report(counter);
    delete counter;
    return 0;
}
